// ── Helpers ───────────────────────────────────────────────────────────────────
const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));

// ── Logo mark component — renders all 47 paths in SVG ────────────────────────
interface MarkProps {
  size?: number;         // scale relative to native (default fits ~580px tall in 16:9)
  fill?: string;
  opacity?: number;
  pathFills?: string[];  // per-path fill overrides (length 47)
  pathOpacities?: number[];
  pathTransforms?: string[];
  style?: React.CSSProperties;
}

const MusiniqueMark: React.FC<MarkProps> = ({
  size = 0.32,
  fill = CLAUDE.INK,
  opacity = 1,
  pathFills,
  pathOpacities,
  pathTransforms,
  style,
}) => {
  const w = LOGO_W * size;
  const h = LOGO_H * size;
  return (
    <svg
      width={w} height={h}
      viewBox={`0 0 ${LOGO_W} ${LOGO_H}`}
      style={{ display: 'block', overflow: 'visible', ...style }}
    >
      {MUSINIQUE_PATHS.map((d, i) => (
        <path
          key={i}
          d={d}
          fill={pathFills ? (pathFills[i] ?? fill) : fill}
          opacity={pathOpacities ? (pathOpacities[i] ?? 1) : 1}
          transform={pathTransforms ? (pathTransforms[i] ?? '') : ''}
        />
      ))}
    </svg>
  );
};

// ── Shared beat wrapper ───────────────────────────────────────────────────────
interface TechniqueBeatProps {
  label: string;
  sparkLine: string;
  children: React.ReactNode;
}
const TechniqueBeat: React.FC<TechniqueBeatProps> = ({ label, sparkLine, children }) => {
  const frame = useCurrentFrame();
  const fps = 30;
  const labelIn = spring({ frame, fps, config: { damping: 28, stiffness: 120, mass: 0.9 } });

  return (
    <AbsoluteFill style={{ background: CLAUDE.PAGE, overflow: 'hidden' }}>
      {/* Segment label */}
      <div style={{
        position: 'absolute', top: '5%', left: 0, right: 0,
        display: 'flex', flexDirection: 'column', alignItems: 'center',
        opacity: clamp(labelIn, 0, 1),
        transform: `translateY(${(1 - labelIn) * 8}px)`,
      }}>
        <div style={{
          fontFamily: SERIF, fontSize: 44, fontWeight: 600,
          color: CLAUDE.INK, letterSpacing: '-0.01em', textAlign: 'center',
        }}>{label}</div>
        <div style={{ width: 48, height: 2, background: CLAUDE.SPARK, marginTop: 6 }} />
      </div>

      {/* Mark stage */}
      <div style={{
        position: 'absolute', top: '16%', bottom: '16%', left: 0, right: 0,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
      }}>
        {children}
      </div>

      {/* Spark line */}
      <div style={{
        position: 'absolute', bottom: '5%', left: 0, right: 0,
        display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
        opacity: clamp(spring({ frame: frame - 12, fps, config: { damping: 28, stiffness: 120, mass: 0.9 } }), 0, 1),
      }}>
        <svg width={18} height={18} viewBox="0 0 24 24">
          {Array.from({ length: 8 }, (_, i) => (
            <line key={i} x1={12} y1={12}
              x2={12 + 10 * Math.cos((i * Math.PI) / 4 + 0.2)}
              y2={12 + 10 * Math.sin((i * Math.PI) / 4 + 0.2)}
              stroke={CLAUDE.SPARK} strokeWidth={3.2} strokeLinecap="round" />
          ))}
        </svg>
        <span style={{
          fontFamily: SERIF, fontSize: 28, fontStyle: 'italic', color: CLAUDE.INK,
        }}>{sparkLine}</span>
      </div>
    </AbsoluteFill>
  );
};

// ── B01 Spring Entrance ───────────────────────────────────────────────────────
const SpringEntrance: React.FC = () => {
  const frame = useCurrentFrame();
  const fps = 30;
  const s = spring({ frame, fps, config: { damping: 24, stiffness: 100, mass: 1 } });
  return (
    <TechniqueBeat label="Spring Entrance" sparkLine="Weight, or appearance?">
      <div style={{ transform: `scale(${s})`, opacity: clamp(s, 0, 1) }}>
        <MusiniqueMark />
      </div>
    </TechniqueBeat>
  );
};

// ── B02 Overshoot Spring ──────────────────────────────────────────────────────
const OvershootSpring: React.FC = () => {
  const frame = useCurrentFrame();
  const fps = 30;
  const s = spring({ frame, fps, config: { damping: 7, stiffness: 230, mass: 0.6 } });
  const squash = Math.max(0, Math.sin(Math.PI * clamp(frame / 18, 0, 1)));
  const scaleX = clamp(s, 0, 2) + squash * 0.3;
  const scaleY = clamp(s, 0, 2) - squash * 0.24;
  return (
    <TechniqueBeat label="Overshoot Spring" sparkLine="Physics, or cartoon?">
      <div style={{
        transform: `scaleX(${scaleX}) scaleY(${scaleY})`,
        transformOrigin: 'bottom center',
        opacity: clamp(s * 2, 0, 1),
      }}>
        <MusiniqueMark />
      </div>
    </TechniqueBeat>
  );
};

// ── B03 Per-Path Stagger ──────────────────────────────────────────────────────
const PerPathStagger: React.FC = () => {
  const frame = useCurrentFrame();
  const fps = 30;
  const STAGGER = 3; // frames between each path
  const pathOpacities = MUSINIQUE_PATHS.map((_, i) => {
    const s = spring({ frame: frame - i * STAGGER, fps, config: { damping: 26, stiffness: 150, mass: 0.8 } });
    return clamp(s, 0, 1);
  });
  const pathTransforms = MUSINIQUE_PATHS.map((_, i) => {
    const s = spring({ frame: frame - i * STAGGER, fps, config: { damping: 26, stiffness: 150, mass: 0.8 } });
    const ty = (1 - clamp(s, 0, 1)) * 30;
    return `translateY(${ty})`;
  });
  return (
    <TechniqueBeat label="Per-Path Stagger" sparkLine="Score, bar by bar.">
      <MusiniqueMark pathOpacities={pathOpacities} pathTransforms={pathTransforms} />
    </TechniqueBeat>
  );
};

// ── B04 Draw-On Stroke ────────────────────────────────────────────────────────
// We use evolvePath from @remotion/paths on a subset of paths to keep render time manageable.
// All 47 paths are shown — first as stroke traces, then fill floods.
const DrawOnStroke: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const DRAW_DUR = durationInFrames * 0.6;
  const FILL_START = durationInFrames * 0.5;
  const size = 0.32;
  const w = LOGO_W * size;
  const h = LOGO_H * size;

  // Stagger the trace: each path gets 1/47 of the draw window offset
  const pathFills: string[] = [];
  const strokeElements: React.ReactElement[] = [];

  MUSINIQUE_PATHS.forEach((d, i) => {
    const pathOffset = (i / MUSINIQUE_PATHS.length) * (DRAW_DUR * 0.7);
    const localFrame = frame - pathOffset;
    const traceProgress = clamp(localFrame / (DRAW_DUR * 0.4), 0, 1);
    const fillOpacity = clamp((frame - FILL_START - i * 1.5) / 20, 0, 1);

    pathFills.push(`rgba(61,57,41,${fillOpacity})`);

    let strokeDasharray = 'none', strokeDashoffset = '0';
    if (traceProgress > 0 && traceProgress < 1) {
      try {
        const evolved = evolvePath(traceProgress, d);
        strokeDasharray = evolved.strokeDasharray;
        strokeDashoffset = String(evolved.strokeDashoffset);
      } catch (_) {
        strokeDasharray = '1 0';
        strokeDashoffset = '0';
      }
    }

    if (traceProgress > 0 && fillOpacity < 1) {
      strokeElements.push(
        <path key={`stroke-${i}`} d={d} fill="none"
          stroke={CLAUDE.SPARK} strokeWidth={3}
          strokeDasharray={strokeDasharray === 'none' ? undefined : strokeDasharray}
          strokeDashoffset={strokeDasharray === 'none' ? undefined : strokeDashoffset}
          strokeLinecap="round"
          opacity={traceProgress < 1 ? 1 : Math.max(0, 1 - fillOpacity * 3)}
        />
      );
    }
  });

  return (
    <TechniqueBeat label="Draw-On Stroke" sparkLine="The stroke is the receipt.">
      <svg width={w} height={h} viewBox={`0 0 ${LOGO_W} ${LOGO_H}`} style={{ display: 'block', overflow: 'visible' }}>
        {MUSINIQUE_PATHS.map((d, i) => (
          <path key={`fill-${i}`} d={d} fill={pathFills[i]} />
        ))}
        {strokeElements}
      </svg>
    </TechniqueBeat>
  );
};

// ── B05 Mask Reveal ───────────────────────────────────────────────────────────
const MaskReveal: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const wipeP = clamp(frame / (durationInFrames * 0.45), 0, 1);
  const irisP = clamp((frame - durationInFrames * 0.5) / (durationInFrames * 0.4), 0, 1);
  const useRadial = wipeP >= 1;
  const size = 0.32;
  const w = LOGO_W * size;
  const h = LOGO_H * size;
  const cx = LOGO_W / 2;
  const cy = LOGO_H / 2;
  const maxR = Math.sqrt(cx * cx + cy * cy) * 1.1;

  return (
    <TechniqueBeat label="Mask Reveal" sparkLine="The world opens.">
      <svg width={w} height={h} viewBox={`0 0 ${LOGO_W} ${LOGO_H}`} style={{ display: 'block' }}>
        <defs>
          <clipPath id="musinique-wipe">
            <rect x={0} y={0} width={LOGO_W * wipeP} height={LOGO_H} />
          </clipPath>
          <clipPath id="musinique-iris">
            <circle cx={cx} cy={cy} r={maxR * irisP} />
          </clipPath>
        </defs>
        <g clipPath={useRadial ? 'url(#musinique-iris)' : 'url(#musinique-wipe)'}>
          {MUSINIQUE_PATHS.map((d, i) => <path key={i} d={d} fill={CLAUDE.INK} />)}
        </g>
      </svg>
    </TechniqueBeat>
  );
};

// ── B06 Scale Zoom ────────────────────────────────────────────────────────────
const ScaleZoom: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const half = durationInFrames * 0.5;
  const isLinear = frame < half;
  const linearScale = isLinear
    ? interpolate(frame, [0, half], [8, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })
    : 1;
  const bezierScale = isLinear ? 8 : interpolate(frame, [half, durationInFrames * 0.9], [8, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: (t) => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2,
  });
  const scale = isLinear ? linearScale : bezierScale;
  return (
    <TechniqueBeat label="Scale Zoom" sparkLine="Bezier earns it.">
      <div style={{ transform: `scale(${scale})`, transformOrigin: 'center center' }}>
        <MusiniqueMark fill={isLinear ? CLAUDE.INK_SOFT : CLAUDE.INK} />
      </div>
    </TechniqueBeat>
  );
};

// ── B07 Rotation ──────────────────────────────────────────────────────────────
const Rotation: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const fps = 30;
  const entryS = spring({ frame, fps, config: { damping: 18, stiffness: 160, mass: 0.8 } });
  const entranceFrames = fps * 1.2;
  const pivot = interpolate(1 - entryS, [0, 1], [0, -45]);
  const continuous = frame > entranceFrames
    ? interpolate(frame - entranceFrames, [0, durationInFrames - entranceFrames], [0, 180])
    : 0;
  return (
    <TechniqueBeat label="Rotation" sparkLine="Meditative, or lazy?">
      <div style={{
        transform: `rotate(${pivot + continuous}deg)`,
        opacity: clamp(entryS, 0, 1),
      }}>
        <MusiniqueMark />
      </div>
    </TechniqueBeat>
  );
};

// ── B08 Skew And Shear ────────────────────────────────────────────────────────
const SkewAndShear: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const fps = 30;
  const leanIn = spring({ frame, fps, config: { damping: 22, stiffness: 140, mass: 0.9 } });
  const holdUntil = durationInFrames * 0.6;
  const releaseP = clamp((frame - holdUntil) / (durationInFrames * 0.3), 0, 1);
  const skewAngle = interpolate(leanIn, [0, 1], [0, 16]) * (1 - releaseP);
  return (
    <TechniqueBeat label="Skew And Shear" sparkLine="Speed, or just cheap?">
      <div style={{
        transform: `skewX(${skewAngle}deg)`,
        opacity: clamp(leanIn, 0, 1),
      }}>
        <MusiniqueMark />
      </div>
    </TechniqueBeat>
  );
};

